    r.check("Mdaddy menu stays inside the window", app.js("(() => { const r=document.getElementById('brand-menu').getBoundingClientRect(); return r.left>=0 && r.top>=0 && r.right<=innerWidth && r.bottom<=innerHeight; })()"))
    r.check("brand menu contains only the four specified icon entries", app.js("(() => { const b=[...document.querySelectorAll('#brand-menu > button')]; return b.length === 4 && b.every(x => !!x.querySelector('img')); })()"))
    r.check("Mdaddy menu has Save and a Save As dropdown", app.js("!!document.getElementById('brand-save') && !!document.getElementById('brand-save-as-toggle') && !!document.getElementById('brand-save-as')"))
    app.js("document.getElementById('brand-save-as-toggle').click()")
    r.check("Save As dropdown expands", app.js("!document.getElementById('brand-save-as-menu').hidden && document.getElementById('brand-save-as-toggle').getAttribute('aria-expanded')==='true'"))
    app.js("document.getElementById('btn-brand-menu').click()")
    r.check("main-app brand is compact and left-aligned", app.js("(() => { const mark=document.getElementById('btn-brand-logo').getBoundingClientRect(), word=document.getElementById('brand-wordmark').getBoundingClientRect(), menu=document.getElementById('btn-brand-menu').getBoundingClientRect(); return mark.left <= 6 && menu.right < 180; })()"))
    r.check("format toolbar shares the top row and right-aligns with padding", app.js("(() => { const b=document.getElementById('toolbar').getBoundingClientRect(), brand=document.getElementById('brand-wrap').getBoundingClientRect(), t=document.querySelector('#toolbar .vditor-toolbar').getBoundingClientRect(); return t.left >= brand.right-1 && b.right-t.right >= 8 && t.top < b.bottom; })()"))
    r.check("word-count number is not shown in the toolbar", app.js("(() => { const c=document.querySelector('#toolbar .vditor-counter'); return !c || getComputedStyle(c).display === 'none'; })()"))
    r.check("main logo is half-size", app.js("(() => { const m=document.querySelector('#btn-brand-logo img').getBoundingClientRect(), w=document.getElementById('brand-wordmark').getBoundingClientRect(); return m.width <= 17 && w.width <= 51; })()"))
    r.check("toolbar wraps when available width shrinks", app.js("(() => { const b=document.getElementById('toolbar'), t=document.querySelector('#toolbar .vditor-toolbar'), old=b.style.width; b.style.width='420px'; const wraps=t.getBoundingClientRect().height > 30; b.style.width=old; return wraps; })()"))
    app.js("(() => { const t=document.getElementById('toolbar'); t.dispatchEvent(new MouseEvent('contextmenu',{bubbles:true,cancelable:true,clientX:120,clientY:20})); })()")
