    app.send("Input.dispatchMouseEvent", {"type": "mouseMoved", "x": 22, "y": 300, "button": "left", "buttons": 1})
    app.send("Input.dispatchMouseEvent", {"type": "mouseReleased", "x": 22, "y": 300, "button": "left", "buttons": 0})
    r.check("dragging toolbar to left edge shows one compact icon column", app.js("(() => { const t=document.getElementById('toolbar'), v=t.querySelector('.vditor-toolbar'), h=t.querySelector('[data-tag=\\\"h1\\\"]'); return t.dataset.dock==='left' && !t.classList.contains('toolbar-move-mode') && v.getBoundingClientRect().width<=44 && v.scrollWidth<=v.clientWidth+2 && (!h || h.getBoundingClientRect().width===0); })()"))
    r.check("Reader and Search stack vertically and indent icons center in the side rail", app.js("(() => { const t=document.getElementById('toolbar'), c=document.getElementById('text-color-controls'), r=document.getElementById('btn-reader-toggle').getBoundingClientRect(), f=document.getElementById('btn-toolbar-find').getBoundingClientRect(), x=t.getBoundingClientRect().left+t.getBoundingClientRect().width/2, i=['outdent','indent','bold','italic'].map(k=>document.querySelector(`#toolbar [data-type=\\\"${k}\\\"]`).getBoundingClientRect().left+document.querySelector(`#toolbar [data-type=\\\"${k}\\\"]`).getBoundingClientRect().width/2); return getComputedStyle(c).flexDirection==='column' && r.top!==f.top && Math.abs(r.left+r.width/2-x)<2 && Math.abs(f.left+f.width/2-x)<2 && i.every(v=>Math.abs(v-x)<2); })()"))
    app.js("document.getElementById('btn-brand-menu').click()")
    r.check("Mdaddy menu stays visible beside the vertical rail", app.js("(() => { const r=document.getElementById('brand-menu').getBoundingClientRect(); return !document.getElementById('brand-menu').hidden && r.left>=0 && r.right<=innerWidth && r.bottom<=innerHeight; })()"))
    app.js("document.getElementById('btn-brand-menu').click()")
    app.js("(() => { const t=document.getElementById('toolbar'); t.dispatchEvent(new MouseEvent('contextmenu',{bubbles:true,cancelable:true,clientX:20,clientY:100})); })()")
    sideStart = app.js("(() => { const r=document.getElementById('brand-wrap').getBoundingClientRect(); return {x:r.left+r.width/2,y:r.top+r.height/2}; })()")
    app.send("Input.dispatchMouseEvent", {"type": "mousePressed", "x": sideStart["x"], "y": sideStart["y"], "button": "left", "buttons": 1})
    app.send("Input.dispatchMouseEvent", {"type": "mouseMoved", "x": 140, "y": 20, "button": "left", "buttons": 1})
    app.send("Input.dispatchMouseEvent", {"type": "mouseReleased", "x": 140, "y": 20, "button": "left", "buttons": 0})
    r.check("dragging toolbar back to top restores horizontal layout", app.wait("document.getElementById('toolbar').dataset.dock==='top'", 3))
    r.check("H, B, and i use matched glyph sizing and requested styles", app.js("(() => { const q=x=>document.querySelector(`#toolbar [data-type=\\\"${x}\\\"] .mdaddy-toolbar-glyph`); const h=q('headings'), b=q('bold'), i=q('italic'); return !!h&&!!b&&!!i&&h.getBoundingClientRect().width===b.getBoundingClientRect().width&&b.getBoundingClientRect().width===i.getBoundingClientRect().width&&getComputedStyle(h).fontWeight==='700'&&getComputedStyle(b).fontWeight==='700'&&getComputedStyle(i).fontStyle==='italic'; })()"))
    app.js("document.querySelector('#toolbar [data-type=\"headings\"]').click()")
    r.check("heading menu shows H1 largest and H6 smallest at modest sizes", app.js("(() => { const s=n=>parseFloat(getComputedStyle(document.querySelector(`#toolbar [data-tag=\\\"h${n}\\\"]`)).fontSize); const z=[1,2,3,4,5,6].map(s); return z.every(Number.isFinite) && z.every((v,i)=>i===0 || z[i-1]>v) && z[0]<=16 && z[5]>=11; })()"))
    app.js("document.querySelector('#toolbar [data-type=\"headings\"]').click()")
    app.js("""(() => { const root=document.querySelector('#editor .vditor-reset'); root.focus(); document.execCommand('insertText',false,'beforeafter'); const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT); let n; while(n=w.nextNode()) if(n.nodeValue==='beforeafter') { const r=document.createRange(); r.setStart(n,6); r.collapse(true); const s=getSelection(); s.removeAllRanges(); s.addRange(r); return true; } return false; })()""")
    app.js("window.__codeBlocksBeforeLine=document.querySelectorAll('#editor .vditor-wysiwyg__block[data-type=code-block]').length; document.querySelector('#toolbar [data-type=\"line\"]').click()")
    r.check("line button splits the sentence and inserts a visible horizontal rule without a code block", app.wait("(() => { const root=document.querySelector('#editor .vditor-reset'), hr=root.querySelector('hr'); return !!hr && getComputedStyle(hr).display!=='none' && hr.getBoundingClientRect().height>0 && hr.previousElementSibling?.textContent.includes('before') && hr.nextElementSibling?.textContent.includes('after') && document.querySelectorAll('#editor .vditor-wysiwyg__block[data-type=code-block]').length===window.__codeBlocksBeforeLine; })()", 5))
    app.js("""(() => { const root=document.querySelector('#editor .vditor-reset'); root.focus(); document.execCommand('insertText',false,'XY'); const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT); let n; while(n=w.nextNode()) if(n.nodeValue==='XY') { const range=document.createRange(); range.setStart(n,0); range.collapse(true); const sel=getSelection(); sel.removeAllRanges(); sel.addRange(range); return true; } return false; })()""")
    app.key("Delete", "Delete", 0, 46)
    r.check("Delete removes the character after the caret", app.wait("document.querySelector('#editor .vditor-reset').innerText.includes('Y') && !document.querySelector('#editor .vditor-reset').innerText.includes('XY')", 3))
    app.js("""(() => { const root=document.querySelector('#editor .vditor-reset'); const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT); let n; while(n=w.nextNode()) if(n.nodeValue==='before') { const r=document.createRange(); r.setStart(n,0); r.collapse(true); const s=getSelection(); s.removeAllRanges(); s.addRange(r); const d=new DataTransfer(); d.setData('text/plain','first URL\\nsecond URL\\nthird URL'); const e=new ClipboardEvent('paste',{clipboardData:d,bubbles:true,cancelable:true}); root.dispatchEvent(e); return true; } return false; })()""")
    r.check("multiline plain paste stays at the caret with visible breaks and no inline code", app.wait("(() => { const root=document.querySelector('#editor .vditor-reset'), t=root.innerText; return t.indexOf('first URL')>=0 && t.indexOf('first URL')<t.indexOf('second URL') && t.indexOf('second URL')<t.indexOf('third URL') && t.indexOf('third URL')<t.indexOf('before') && ![...root.querySelectorAll('code')].some(c=>c.textContent.includes('first URL')); })()", 5))
    app.js("""(() => { const root=document.querySelector('#editor .vditor-reset'); root.focus(); const range=document.createRange(); range.selectNodeContents(root); range.collapse(false); const selection=getSelection(); selection.removeAllRanges(); selection.addRange(range); const d=new DataTransfer(); d.setData('text/plain','https://one.example.test/a\\nhttps://two.example.test/b'); const e=new ClipboardEvent('paste',{clipboardData:d,bubbles:true,cancelable:true}); root.dispatchEvent(e); return true; })()""")
    r.check("pasted URLs become clickable links on separate lines", app.wait("(() => { const root=document.querySelector('#editor .vditor-reset'), a=[...root.querySelectorAll('a')].filter(x=>x.href.includes('.example.test')); return a.length===2 && a[0].getBoundingClientRect().top < a[1].getBoundingClientRect().top; })()", 5))
    app.js("""(() => { const root=document.querySelector('#editor .vditor-reset'); const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT); let n; while(n=w.nextNode()) if(n.nodeValue==='after') { const r=document.createRange(); r.setStart(n,2); r.collapse(true); const s=getSelection(); s.removeAllRanges(); s.addRange(r); return true; } return false; })()""")
    app.key("h", "KeyH", 10, 72)
    r.check("Ctrl+Shift+H inserts a rule at the caret", app.wait("(() => { const root=document.querySelector('#editor .vditor-reset'), hrs=[...root.querySelectorAll('hr')]; return hrs.length===2 && hrs[1].previousElementSibling?.textContent.includes('af') && hrs[1].nextElementSibling?.textContent.includes('ter'); })()", 5))
    r.check("quote and task-list icons use the requested artwork", app.js("!!document.querySelector('#toolbar [data-type=quote] .mdaddy-quote-glyph') && !!document.querySelector('#toolbar [data-type=check] .mdaddy-check-glyph path')"))
    r.check("Reader, Find, and text-color controls have consistent unoutlined sizing", app.js("(() => { const ids=['btn-reader-toggle','btn-toolbar-find','text-color-button']; const bs=ids.map(id=>document.getElementById(id).getBoundingClientRect()); return bs.every(b=>b.width===bs[0].width&&b.height===bs[0].height) && ids.every(id=>getComputedStyle(document.getElementById(id)).borderStyle==='none' || getComputedStyle(document.getElementById(id)).borderWidth==='0px'); })()"))

    app.js("document.getElementById('btn-toolbar-find').click()")
    r.check("magnifier opens Find", app.js("!document.getElementById('find-bar').hidden"))
    app.js("document.getElementById('btn-toolbar-find').click()")
    r.check("magnifier closes Find", app.js("document.getElementById('find-bar').hidden"))

