    r.check("Firefox multi-tab drag creates linked Markdown bullets", app.wait("(() => { const a=[...document.querySelectorAll('#editor .vditor-reset li a')]; return a.some(x => x.textContent==='Example Docs' && x.href==='https://docs.example.test/guide') && a.some(x => x.textContent==='Start Page' && x.href==='https://example.test/start'); })()", 5))
    app.js("""(() => { const dt=new DataTransfer(); dt.setData('text/html','<a href="https://developer.example.test/">Developer Guide</a><a href="https://support.example.test/">Support</a>'); dt.setData('text/uri-list','https://developer.example.test/\\nhttps://support.example.test/'); window.dispatchEvent(new DragEvent('drop',{dataTransfer:dt,bubbles:true,cancelable:true})); })()""")
    r.check("Chrome HTML tab group keeps titles and target URLs", app.wait("(() => { const a=[...document.querySelectorAll('#editor .vditor-reset li a')]; return a.some(x => x.textContent==='Developer Guide' && x.href==='https://developer.example.test/') && a.some(x => x.textContent==='Support' && x.href==='https://support.example.test/'); })()", 5))
